def build_qft_circuit(self, n_qubits, inverse=False):
    """Build QFT circuit."""
    qft = QuantumCircuit(n_qubits, name=f'{"IQFT" if inverse else "QFT"}')

    if not inverse:
        for i in range(n_qubits - 1, -1, -1):
