"""Gates."""

from __future__ import annotations

from typing import Optional

import numpy as np
from qiskit import QuantumCircuit, QuantumRegister
from qiskit.circuit.gate import Gate
from qiskit.circuit.library import RZXGate, RZGate, U3Gate, XGate
from qiskit.circuit.parameterexpression import ParameterValueType
from qiskit.qasm import pi


class XpGate(Gate):
    r"""The single-qubit Pauli-X gate (:math:`\sigma_x`), implemented
    via RX(\pi).
    """

    def __init__(self, label: Optional[str] = None):
        """Create new Xp gate."""
        super().__init__("xp", 1, [], label=label)

    def _define(self):
        """
        gate xp a { u3(pi,0,pi) a; }
        """
        q = QuantumRegister(1, "q")
        qc = QuantumCircuit(q, name=self.name)
        rules = [(U3Gate(pi, 0, pi), [q[0]], [])]
        for instr, qargs, cargs in rules:
            qc.append(instr, qargs, cargs)

        self.definition = qc

    def inverse(self):
        r"""Gate inverse."""
        return XmGate()

    def __array__(self, dtype=None):
        """Gate matrix."""
        return np.array([[0, 1], [1, 0]], dtype=dtype)


class XmGate(Gate):
    r"""The single-qubit Pauli-X gate (:math:`\sigma_x`), implemented
    via RX(-\pi).
    """

    def __init__(self, label: Optional[str] = None):
        """Create new Xm gate."""
        super().__init__("xm", 1, [], label=label)

    def _define(self):
        """
        gate xm a { u3(pi,0,pi) a; }
        """
        q = QuantumRegister(1, "q")
        qc = QuantumCircuit(q, name=self.name)
        rules = [(U3Gate(pi, 0, pi), [q[0]], [])]
        for instr, qargs, cargs in rules:
            qc.append(instr, qargs, cargs)

        self.definition = qc

    def inverse(self):
        r"""Gate inverse."""
        return XpGate()

    def __array__(self, dtype=None):
        """Gate matrix"""
        return np.array([[0, 1], [1, 0]], dtype=dtype)


class YpGate(Gate):
    r"""The single-qubit Pauli-Y gate (:math:`\sigma_y`), implemented
    via RY(\pi).
    """

    def __init__(self, label: Optional[str] = None):
        """Create new Yp gate."""
        super().__init__("yp", 1, [], label=label)

    def _define(self):
        q = QuantumRegister(1, "q")
        qc = QuantumCircuit(q, name=self.name)
        rules = [(U3Gate(pi, pi / 2, pi / 2), [q[0]], [])]
        for instr, qargs, cargs in rules:
            qc.append(instr, qargs, cargs)

        self.definition = qc

    def inverse(self):
        r"""Return inverted Yp gate (:math:`Y{\dagger} = Y`)"""
        return YmGate()  # self-inverse

    def __array__(self, dtype=None):
        """Gate matrix."""
        return np.array([[0, -1j], [1j, 0]], dtype=dtype)


class YmGate(Gate):
    r"""The single-qubit Pauli-Y gate (:math:`\sigma_y`), implemented
    via RY(-\pi).
    """

    def __init__(self, label: Optional[str] = None):
        """Create new Ym gate."""
        super().__init__("ym", 1, [], label=label)

    def _define(self):
        q = QuantumRegister(1, "q")
        qc = QuantumCircuit(q, name=self.name)
        rules = [(U3Gate(pi, pi / 2, pi / 2), [q[0]], [])]
        for instr, qargs, cargs in rules:
            qc.append(instr, qargs, cargs)

        self.definition = qc

    def inverse(self):
        r"""Return inverted Ym gate (:math:`Y{\dagger} = Y`)"""
        return YpGate()  # self-inverse

    def __array__(self, dtype=None):
        """Gate matrix."""
        return np.array([[0, -1j], [1j, 0]], dtype=dtype)


class PiPhiGate(Gate):
    r"""
    Rotated X gate.

    The 180-degree rotation about an axis offset by an angle :math:`\\phi` relative
    to the X-axis in the XY-plane of the Bloch sphere.
    """

    def __init__(
        self,
        phi: ParameterValueType,
        label: Optional[str] = None,
    ):
        """Create new PiPhi gate."""
        super().__init__("pi_phi", 1, [phi], label=label)
        self.phi = phi

    def _define(self):
        q = QuantumRegister(1, "q")
        qc = QuantumCircuit(q, name=self.name)
        rules = [
            (RZGate(self.phi), [q[0], []]),
            (XGate(), [q[0]], []),
            (RZGate(-self.phi), [q[0]], []),
        ]
        for instr, qargs, cargs in rules:
            qc.append(instr, qargs, cargs)

        self.definition = qc

    def inverse(self):
        r"""Return inverted PiPhi gate (:math:`\pi_\phi{\dagger}(\phi) = \pi_\phi(-\phi)`)"""
        return PiPhiGate(-self.phi)  # self-inverse

    def __array__(self, dtype=None):
        """Gate matrix."""
        return np.cos(self.phi) * np.array([[0, 1], [1, 0]], dtype=dtype) + np.sin(
            self.phi
        ) * np.array([[0, -1j], [1j, 0]], dtype=dtype)


class SECRGate(Gate):
    r"""The scaled echoed cross resonance gate, as detailed in
    https://arxiv.org/abs/1603.04821 and
    https://arxiv.org/abs/2202.12910.

    Definitions are derived by appending an XGate() to q0
